import json
import re
import subprocess
import time

from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.connection_manager.communicator import Communicator
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class NIDDFileOperations:
    def __init__(self):
        self.nidd_content = None

    def fetch_nidd_content(self, local_ip):
        """
        Function fetches nidd content.

        nidd file will be copied from /rom/swpool/OAM/, if RAT is commissioned. Else it will be copied from /rom/
        directly.

        nidd file version depends on the current active build on the BTS

        :param local_ip: str, ip of the locally configured BTS

        :returns : nidd content
        :rtype : json

        """
        if self.nidd_content:
            return self.nidd_content

        config = get_config_variable(["bts"])

        server = local_ip
        user = "ute"
        password = ""
        nidd_filename = "nidd_*.json"
        local_nidd_path = "execution_logs/"
        admin_user = config["user"]
        admin_password = config["password"]
        admin_ip = config["ip"]

        cur_path = subprocess.check_output('pwd', shell=True).decode('utf-8').strip()
        local_nidd_path = cur_path+"/"+local_nidd_path

        # Check in swpool path
        remote_nidd_path = "/rom/swpool/OAM/{}".format(nidd_filename)
        command = "sshpass -p {0} scp {1}@{2}:{3} {4}".format(admin_password, admin_user, admin_ip, remote_nidd_path,
                                                              local_nidd_path)
        remote_conn = Communicator()
        remote_conn.execute_command_remotely(ip=server, username=user, password=password, command=command)

        # Check directly under rom
        remote_nidd_path = "/rom/{}".format(nidd_filename)
        command = "sshpass -p {0} scp {1}@{2}:{3} {4}".format(admin_password,  admin_user, admin_ip, remote_nidd_path,
                                                              local_nidd_path)
        logger.debug("COMMAND {}".format(command))
        remote_conn.execute_command_remotely(ip=server, username=user, password=password, command=command)

        time.sleep(2)
        logger.debug("#### Find NIDD file")
        output = subprocess.check_output('find {}{}'.format(local_nidd_path, nidd_filename), shell=True).decode('utf-8')
        logger.debug("############## {}".format(output))
        self.nidd_file = re.search(r'(nidd_[A-Za-z0-9]+)\.json', output, re.DOTALL).group()

        if self.nidd_file:
            local_path_to_nidd_file = "{}{}".format(local_nidd_path, self.nidd_file)
            with open(local_path_to_nidd_file) as nidd:
                self.nidd_content = json.load(nidd)
            logger.debug("Successfully fetched NIDD content \n #########################################")
            return self.nidd_content
        else:
            raise Exception("Failed to copy NIDD file")

    def get_nidd_parameter(self, parent_mo):
        """
        Get all nidd parameter for the given parent_mo

        :param parent_mo: str, Parent managed Object to fetch the parameters.

        :returns nidd_content
        :rtype dict
        """
        self.fetch_nidd_content('127.0.0.1')
        nidd_param = {}
        nidd_param_list = list(self.nidd_content[parent_mo]['params'].keys())
        for each_nidd_param in nidd_param_list:
            if self.nidd_content[parent_mo]['params'][each_nidd_param]['type'].lower() == 'complex':
                nidd_param[each_nidd_param] = list(
                    self.nidd_content[parent_mo]['params'][each_nidd_param]['params'].keys())
            else:
                nidd_param[self.nidd_content[parent_mo]['params'][each_nidd_param]['name']] = None
        return nidd_param

    def get_parameters_default_value_from_nidd(self, parent_mo, parameter, sub_parameter=None):
        """
        Function gets default value of the given parameter from nidd

        :param parent_mo: str, parent moc
        :param parameter: str, name of the parameter to fetch the default value
        :param sub_parameter: str, None if parameter is simple, otherwise name of the parameter must be specified.

        :returns value for the given parameter
        :rtype int/str/bool, return type depends on the value present in the nidd file
        """
        self.fetch_nidd_content('127.0.0.1')
        if sub_parameter:
            return self.nidd_content[parent_mo]['params'][parameter]['params'][sub_parameter].get('default')
        else:
            return self.nidd_content[parent_mo]['params'][parameter].get('default')

    def fetch_new_default_value(self, parent_mo, parameter, sub_parameter=None):
        """
        Function to decide default value from enumeration or minIncl values for a given parameter where default is
        not specified.

        :param parent_mo: str, parent moc
        :param parameter: str, name of the parameter to fetch the default value
        :param sub_parameter: str, None if parameter is simple, otherwise name of the parameter must be specified.

        :returns value for the given parameter
        :rtype int/str/bool, return type depends on the value present in the nidd file
        """
        non_default_param = {'minIncl', 'minLength', 'enumeration'}
        parent_params = self.fetch_parameter_dependencies_from_nidd(parent_mo=parent_mo, parameter=parameter,
                                                                    sub_parameter=sub_parameter)
        parent_params_keys = set(parent_params.keys())
        val_type = parent_params_keys & non_default_param
        if not val_type:
            logger.info("Parameter {} has no default/enumeration/minInc/MinLength present in its structure {} ".format(
                parameter, parent_params))
        else:
            val_type = val_type.pop()

        if "enumeration" == val_type:
            logger.info("Parameters {} default value has been fetched from {}".format(parameter, val_type))
            return min([d['value'] for d in parent_params['enumeration']])
        elif 'minIncl' == val_type:
            logger.info("Parameters {} default value has been fetched from {}".format(parameter, val_type))
            return parent_params[val_type]
        else:
            logger.info("Parameter {}/{} is of range type {}, it is not yet supported by auto correction".format(
                parameter, sub_parameter, val_type))

    def fetch_parameter_dependencies_from_nidd(self, parent_mo, parameter, sub_parameter=None):
        """
        Function to fetch parameter dependencies like Modification Type, change priority etc.

        :param parent_mo: str, Parent moc
        :param parameter: str, name of the parameter to fetch the dependencies
        :param sub_parameter: str, None if parameter is simple, otherwise dependencies will be picked for the
            parameter name mentioned in this argument rather than above parameter argument.
            sub_parameter takes precedence over parameter argument in case of complex type parameter

        :returns Below structure will be returned
            {
                  'type': 'simple',
                  'base': 'decimal',
                  'minIncl': 2,
                  'maxIncl': 3,
                  'step': 1,
                  'parentMO': 'LNADJGNB',
                  'name': 'mncLength',
                  'fullName': 'MNC length in primary PLMN of neighbor gNB',
                  'modificationType': 0,
                  'creationPriority': 0
            }
        :rtype dictionary
        """
        self.fetch_nidd_content('127.0.0.1')
        if sub_parameter:
            return self.nidd_content[parent_mo]['params'][parameter]['params'][sub_parameter]
        return self.nidd_content[parent_mo]['params'][parameter]

    def is_default_present_in_nidd(self, parent_mo, parameter, sub_parameter=None):
        """
        Function to check if default value is present for the given parameter

        :param parent_mo: str, parent moc
        :param parameter: str, name of the parameter to fetch the dependencies
        :param sub_parameter: str, None if parameter is simple, otherwise name of the parameter must be specified.

        :returns True or False, True if default value is present else False
        :rtype bool
        """
        self.fetch_nidd_content('127.0.0.1')
        if sub_parameter:
            return self.nidd_content[parent_mo]['params'][parameter]['params'][sub_parameter].get('default') is \
                   not None
        else:
            return self.nidd_content[parent_mo]['params'][parameter].get('default') is not None
